namespace StationApp.Ai;

// =====================================================================
//  ЖИ: ФАЙЛЫ ЗНАНИЙ ПО УМОЛЧАНИЮ  [ДОБАВЛЕНО 28.10.2026]
//  Пишутся в папку Knowledge рядом со Station.exe, если их там нет (или там старая версия — тогда
//  старый файл сохраняется с «_старая_копия» в имени). Преподаватель может править их без пересборки.
//  Формат строки: слова через запятую | по-русски | қазақша. Слова — любые формы и синонимы, ЖИ сам
//  приводит их к основе (маршрутты → маршрут, жасау = задать = сделать).
// =====================================================================

static class AiDefaults
{
    public const string HelpFile = "Справка_по_интерфейсу.txt";
    // [ИЗМЕНЕНО 10.11.2026] не const, а свойства: у программы «Станция по схеме» название станции известно только
    // после чтения JSON (у АКЖТ и Алгабаса AiProfile по-прежнему константы — для них ничего не меняется)
    public static string HelpVersion => "# версия справки: 3.4 (" + AiProfile.Station + ", 06.11.2026)";

    // [ИЗМЕНЕНО 06.11.2026] строки, свои у АКЖТ и Алгабаса (Arduino, связь, переезд, «Вид»…), — в AiProfile.HelpLines
    public static string Help => HelpVersion + @"
# Справка ИИ-помощника (ЖИ-көмекші) по программе станции " + AiProfile.Station + @" (новый интерфейс: режимы, «Параметры», пульт ДСП).
# Формат строки:  слова (синонимы, через запятую) | ответ по-русски | жауап қазақша
# Правьте, добавляйте строки — перезапуск не нужен (файл перечитывается при изменении). Кодировка UTF-8.

как задать маршрут, задать маршрут, сделать маршрут, создать маршрут, поставить маршрут, набрать маршрут, маршрут жасау, маршрут беру, маршрут құру, маршрутты беру, маршрутты жасау | Чтобы задать маршрут: 1) внизу выберите ПОЕЗДНЫЕ (приём и отправление) или МАНЕВРОВЫЕ; 2) щёлкните левой кнопкой мыши светофор начала маршрута; 3) щёлкните светофор конца или путь назначения. Стрелки переведутся сами, маршрут мигает, пока устанавливается, и светофор откроется. То же — клик по названию маршрута в списке «Маршруты». Пример: " + AiProfile.HelpExampleRu + @" Ошиблись светофором начала — кнопка «Отмена набора». | Маршрут беру үшін: 1) төменнен ПОЕЗДНЫЕ (пойызды қабылдау және жөнелту) немесе МАНЕВРОВЫЕ батырмасын таңдаңыз; 2) маршрут басталатын светофорды тінтуірдің сол жақ батырмасымен басыңыз; 3) соңғы светофорды немесе баратын жолды басыңыз. Стрелкалар өздері ауысады, маршрут орнатылып жатқанда жыпылықтайды, содан соң светофор ашылады. Сол сияқты «Маршруты» тізіміндегі маршрут атауын басуға болады. Мысалы: " + AiProfile.HelpExampleKk + @" Басталу светофорын қате басқан болсаңыз — «Отмена набора» батырмасы.
отменить маршрут, отмена маршрута, снять маршрут, маршрутты болдырма, маршрутты жою, маршрутты алып таста | Отменить маршрут: правая кнопка мыши по светофору начала → «Отменить…», повторный клик по маршруту в списке или кнопка «Отменить маршрут» (последний заданный). Если светофор уже был открыт, отмена идёт с выдержкой времени: горят лампы ОС (6 с), ОП (поездной при занятом приближении, 3 мин) или ОМ (маневровый, 1 мин). Если поезд уже вошёл в маршрут, маршрут разомкнётся сам за поездом. | Маршрутты болдырмау: басталу светофорын тінтуірдің оң жақ батырмасымен басып → «Отменить…», тізімдегі маршрутты қайта басу немесе «Отменить маршрут» батырмасы (соңғы берілгені). Светофор ашылып қойған болса, болдырмау уақыт ұстаумен жүреді: ОС (6 с), ОП (жақындау учаскесі бос емес пойыз маршруты, 3 мин) немесе ОМ (маневрлік, 1 мин) шамдары жанады. Пойыз маршрутқа кіріп кетсе, маршрут пойыздың артынан өзі ажырайды.
отмена набора | Кнопка «Отмена набора» сбрасывает нажатый светофор начала, если вы щёлкнули не тот светофор (маршрут ещё не задан). | «Отмена набора» батырмасы маршрут әлі берілмей тұрып басылған басталу светофорын тастайды (қате светофорды басқанда).
поездные, маневровые, поездной маршрут, маневровый маршрут, пойыз маршруты, маневрлік маршрут | ПОЕЗДНЫЕ — маршруты приёма и отправления поездов (светофор открывается жёлтым или зелёным). МАНЕВРОВЫЕ — маршруты для манёвров (горит лунно-белый огонь, путь назначения может быть занят). Кнопки выбирают, какие маршруты задаются кликом и показываются в списке. | ПОЕЗДНЫЕ — пойызды қабылдау және жөнелту маршруттары (светофор сары немесе жасыл болып ашылады). МАНЕВРОВЫЕ — манёвр маршруттары (ай-ақ от жанады, баратын жол бос емес болуы мүмкін). Бұл батырмалар басу арқылы қандай маршрут берілетінін және тізімде не көрсетілетінін таңдайды.
перевести стрелку, перевод стрелки, стрелканы ауыстыру, переключить стрелку | Стрелку переводят левой кнопкой мыши по её номеру на схеме или кнопкой стрелки в колонке «Стрелки» (в павлодарском режиме — кнопки «+» и «−»). «+» — прямо, «−» — на отклонение. Если стрелка заперта маршрутом, замкнута кнопкой ЗС/ЧЗС/НЗС или её участок занят, перевести нельзя. При ложной занятости — вспомогательный перевод (правая кнопка мыши, кнопка ВК со счётчиком). | Стрелканы схемадағы нөмірін тінтуірдің сол жақ батырмасымен басып немесе «Стрелки» бағанындағы батырмасымен ауыстырады (павлодар режимінде — «+» және «−» батырмалары). «+» — түзу, «−» — бұрылысқа. Стрелка маршрутпен құлыпталса, ЗС/ЧЗС/НЗС батырмасымен тұйықталса немесе оның учаскесі бос емес болса, ауыстыруға болмайды. Жалған бос еместікте — көмекші ауыстыру (тінтуірдің оң жағы, санағышы бар ВК батырмасы).
пригласительный, пригласительный сигнал, шақыру сигналы, пс | Пригласительный сигнал — красный и мигающий лунно-белый огонь. Его включают, когда обычный сигнал открыть нельзя (например, ложная занятость рельсовой цепи): правая кнопка мыши по входному светофору → «Пригласительный сигнал…» или кнопка «ПС …». Нужен маршрут, заданный по стрелкам; поезд идёт не быстрее 20 км/ч. Каждое нажатие записывается в журнал ДУ-46. | Шақыру сигналы — қызыл және жыпылықтайтын ай-ақ от. Әдеттегі сигналды ашу мүмкін болмағанда қосылады (мысалы, рельс тізбегінің жалған бос еместігі): кіру светофорын тінтуірдің оң жағымен басып → «Пригласительный сигнал…» немесе «ПС …» батырмасы. Стрелкалар бойынша берілген маршрут керек; пойыз сағатына 20 км-ден аспай жүреді. Әр басу ДУ-46 журналына жазылады.
направление перегона, сменить направление, смена направления, бағытты ауыстыру, перегон бағыты | Направление однопутного перегона меняет кнопка «Сменить направление». Перегон должен быть свободен, маршруты на перегон — отменены, и соседняя станция должна дать согласие. Если перегон занят ложно — «Вспом. смена…» (ВСН, кнопка со счётчиком, запись в ДУ-46). | Бір жолды перегонның бағытын «Сменить направление» батырмасы ауыстырады. Перегон бос болуы, перегонға берілген маршруттар болдырылмауы және көрші станция келісуі керек. Перегон жалған бос емес болса — «Вспом. смена…» (ВСН, санағышы бар батырма, ДУ-46-ға жазылады).
режим интерфейса, режимы, параметры, инженерный, учебный, рабочий, павлодарский, интерфейс режимі | Кнопка «Параметры» вверху выбирает режим интерфейса: Инженерный — всё, для наладки макета (проверка ламп, порт Arduino, список занятости); Учебный — для занятий, без наладочных панелей; Рабочий — как АРМ ДСП станции Медеу, для работы с настоящим макетом, без имитации поездов; Павлодарский — серая схема и кнопочный пульт «Енисей». Там же галочками можно показать или скрыть любую панель. | Жоғарыдағы «Параметры» батырмасы интерфейс режимін таңдайды: Инженерлік — бәрі, макетті баптауға (шамдарды тексеру, Arduino порты, бос еместік тізімі); Оқу — сабаққа, баптау панельдерінсіз; Жұмыс — Медеу станциясының ДСП АЖО-сы сияқты, нақты макетпен жұмыс, пойыз имитациясынсыз; Павлодарлық — сұр сызба және «Енисей» батырмалы пульті. Сол терезеде белгілермен кез келген панельді көрсетуге немесе жасыруға болады.
кнопочный пульт, енисей, павлодарский пульт, батырмалы пульт | В павлодарском режиме под схемой кнопочный пульт «Енисей»: ряды ПОЕЗДНЫЕ и МАНЕВРОВЫЕ — кнопки светофоров (нажмите кнопку начала, потом конца — маршрут задан, то же ещё раз — отменён); СТРЕЛКИ — «+», номер, «−»; ПУТИ, УЧАСТКИ — во время набора это путь назначения, без набора — искусственная разделка (ИР). | Павлодар режимінде сызба астында «Енисей» батырмалы пульті: ПОЕЗДНЫЕ және МАНЕВРОВЫЕ қатарлары — светофор батырмалары (басталу, содан соң соңғы батырманы басыңыз — маршрут берілді, тағы да басса — болдырылады); СТРЕЛКИ — «+», нөмір, «−»; ПУТИ, УЧАСТКИ — маршрут жинағанда баратын жол, жинамағанда жасанды ажырату (ИР).
пульт дсп, замыкание стрелок, зс, чзс, нзс | Пульт ДСП: ЧЗС, НЗС, ЗС — замыкание чётных, нечётных или всех стрелок (стрелки с пульта не переводятся); ЛКМ — нажать, ПКМ — отжать. Каждое нажатие — счётчик, его нужно записать в журнал ДУ-46. | ДСП пульті: ЧЗС, НЗС, ЗС — жұп, тақ немесе барлық стрелкаларды тұйықтау (стрелкалар пульттен ауыстырылмайды); сол жақ батырма — басу, оң жағы — босату. Әр басу санағышқа түседі, оны ДУ-46 журналына жазу керек.
автодействие, адч, адн | АДЧ и АДН — автодействие светофоров чётного и нечётного направления по главному пути: заданные сквозные маршруты после поезда задаются сами. ЛКМ — включить, ПКМ — выключить. | АДЧ және АДН — бас жол бойынша жұп және тақ бағыттағы светофорлардың автоәрекеті: берілген өтпелі маршруттар пойыздан кейін өздері қайта беріледі. Сол жақ батырма — қосу, оң жағы — өшіру.
искусственная разделка, ир, разделка, жасанды ажырату | ИР — искусственная разделка: если после проследования поезда участки маршрута остались замкнутыми (горят), кнопка «ИР…» на пульте ДСП (или кнопка участка в павлодарском режиме) размыкает их после выдержки времени. Дежурный должен лично убедиться, что участки свободны; нажатие записывается в ДУ-46. | ИР — жасанды ажырату: пойыз өткеннен кейін маршрут учаскелері тұйықталған күйде қалса, ДСП пультіндегі «ИР…» батырмасы (павлодар режимінде — учаске батырмасы) оларды уақыт ұстаудан кейін ажыратады. Кезекші учаскелердің бос екеніне өзі көз жеткізуі керек; басу ДУ-46-ға жазылады.
ключ-жезл, ключ жезл, кілт-жезл | Ключ-жезл на пульте ДСП: изъять, выдать машинисту, забрать, вложить. Пока ключ-жезл изъят, направление перегона менять нельзя, а на перегон по сигналу отправляется только одна единица. | ДСП пультіндегі кілт-жезл: алу, машинистке беру, қайтарып алу, орнына салу. Кілт-жезл алынған кезде перегон бағытын өзгертуге болмайды, перегонға сигнал бойынша тек бір бірлік жөнелтіледі.
убрать всё, сбросить всё, бәрін алып тастау | Кнопка «Убрать всё» (вверху) убирает все поезда и сбрасывает станцию: маршруты, занятость, замыкания. | «Убрать всё» батырмасы (жоғарыда) барлық пойыздарды алып тастап, станцияны бастапқы күйге келтіреді: маршруттар, бос еместік, тұйықтаулар.
поставить поезд, имитация, виртуальный поезд, пойыз қою, убрать поезда | Колонка «Имитация (обучение)»: кнопки поездов с перегонов, «Убрать поезда», «Поставить поезд на путь» (выберите путь, «← поезд» или «поезд →»), скорость (с/участок) и выдержки разделки. Режим поезда — как выбрано кнопкой ПОЕЗДНЫЕ / МАНЕВРОВЫЕ. В рабочем режиме имитации нет — поезда только с макета. | «Имитация (обучение)» бағаны: перегоннан пойыз батырмалары, «Убрать поезда», «Поставить поезд на путь» (жолды таңдап, «← поезд» немесе «поезд →»), жылдамдық (с/учаске) және ажырату уақыттары. Пойыз режимі ПОЕЗДНЫЕ / МАНЕВРОВЫЕ батырмасы бойынша. Жұмыс режимінде имитация жоқ — пойыздар тек макеттен.
занять участок, занять вручную, ложная занятость, учаскені бос емес ету, ручная занятость | Участок можно занять вручную: правая кнопка мыши по пути → «Занять вручную (имитация)» или кнопка участка в списке «Занятость участков» (инженерный режим). Так имитируется поезд или ложная занятость. Снять — тем же способом. В рабочем режиме ручная занятость выключена. | Учаскені қолмен бос емес етуге болады: жолды тінтуірдің оң жағымен басып → «Занять вручную (имитация)» немесе «Занятость участков» тізіміндегі учаске батырмасы (инженерлік режим). Осылай пойыз немесе жалған бос еместік имитацияланады. Алып тастау — сол тәсілмен. Жұмыс режимінде қолмен бос емес ету өшірулі.
журнал ду-46, ду-46, журнал осмотра, неисправность | ДУ-46 — журнал осмотра путей, стрелочных переводов, устройств СЦБ: сюда записывают неисправности и нажатия кнопок со счётчиком (ИР, ВК, ВСН, ПС, ЗС, АДЧ/АДН). Кнопка «ДУ-46» вверху; неисправность — правая кнопка мыши по объекту → «Неисправность…». | ДУ-46 — жолдарды, бағыттамаларды, СЦБ құрылғыларын тексеру журналы: ақаулар мен санағышы бар батырмалардың басылуы (ИР, ВК, ВСН, ПС, ЗС, АДЧ/АДН) жазылады. Жоғарыдағы «ДУ-46» батырмасы; ақау — объектіні оң жақ батырмамен басып → «Неисправность…».
журналы, ду-2, ду-47, ду-58, ду-60, бланки | Кнопка «Журналы ▾»: ДУ-2 (движение поездов), ДУ-47 (поездные телефонограммы), ДУ-58 (поездные депеши), ДУ-60 (приём и сдача дежурства), бланки (ДУ-54, ДУ-64…), поездная радиосвязь, предупреждения. | «Журналы ▾» батырмасы: ДУ-2 (пойыздар қозғалысы), ДУ-47 (телефонограммалар), ДУ-58 (пойыз жеделхаттары), ДУ-60 (кезекшілікті қабылдау және тапсыру), бланкілер (ДУ-54, ДУ-64…), пойыздық радиобайланыс, ескертулер.
радиосвязь, вызвать машиниста, радиобайланыс | Поездная радиосвязь: правая кнопка мыши по поезду → «Вызвать по радиосвязи…»: остановка, указание, осаживание, предупреждение, сократить стоянку, где находитесь, вручить бланк. | Пойыздық радиобайланыс: пойызды оң жақ батырмамен басып → «Вызвать по радиосвязи…»: тоқтату, нұсқау, кері жүру, ескерту, тұрақты қысқарту, қайдасыз, бланк беру.
упрощённый, упрощенный вид, крупные светофоры | «Включить упрощённый» — светофоры на схеме рисуются крупными кругами, как на АРМ ДСП. | «Включить упрощённый» — сызбадағы светофорлар АЖО-дағыдай ірі дөңгелек болып салынады.
язык, тіл, казахский, английский | Язык программы выбирается списком вверху справа (Русский, Қазақша, English). ИИ отвечает на языке вопроса. | Бағдарлама тілі жоғарғы оң жақтағы тізімнен таңдалады (Русский, Қазақша, English). ЖИ сұрақ қойылған тілде жауап береді.
" + AiProfile.HelpLines;

